insert into public.data_sources(id,publisher,category,source_url,status,caution) values ('reconmr-texas-oct-2026','ReconMR / Siena Research Institute','poll_original_release','https://sri.siena.edu/2026/10/13/talarico-maintains-small-lead-over-paxton/','original_release_reviewed','Survey observations, not election results or win probabilities') on conflict(id) do nothing;
insert into public.polls(source_id,original_release_url,external_poll_id,race_id,pollster,sponsor,field_start,field_end,sample_size,population,method,results,published_on,review_status,evidence,review_notes,content_hash)
select source_id,original_release_url,external_poll_id,race_id,pollster,sponsor,field_start,field_end,sample_size,population,method,results,published_on,review_status,evidence,review_notes,encode(extensions.digest(convert_to(original_release_url||external_poll_id||results::text,'UTF8'),'sha256'),'hex') from jsonb_to_recordset('[{"source_id":"reconmr-texas-oct-2026","original_release_url":"https://sri.siena.edu/wp-content/uploads/2026/10/TXP004-October-Press-Release.pdf","external_poll_id":"TXP004-SEN","race_id":"SEN-TX","pollster":"ReconMR","sponsor":null,"field_start":"2026-10-05","field_end":"2026-10-08","sample_size":617,"population":"Likely voters","method":"Dual-frame landline/cell telephone and text-to-web; English and Spanish","results":[{"name":"Ken Paxton","party":"REP","percentage":44},{"name":"James Talarico","party":"DEM","percentage":48},{"name":"Someone else","percentage":2},{"name":"Would not vote","percentage":1},{"name":"Do not know / Refused","percentage":5}],"published_on":"2026-10-13","review_status":"verified","evidence":{"release_pages":[1,3],"crosstabs_url":"https://sri.siena.edu/wp-content/uploads/2026/10/TXP004-Crosstabs.pdf","crosstabs_page":1,"margin_of_error_percentage_points":4.4},"review_notes":"Compared original release against crosstabs. This verifies transcription of this survey, not ballot qualification, poll accuracy or forecast calibration."},{"source_id":"reconmr-texas-oct-2026","original_release_url":"https://sri.siena.edu/wp-content/uploads/2026/10/TXP004-October-Press-Release.pdf","external_poll_id":"TXP004-GOV","race_id":"GOV-TX","pollster":"ReconMR","sponsor":null,"field_start":"2026-10-05","field_end":"2026-10-08","sample_size":617,"population":"Likely voters","method":"Dual-frame landline/cell telephone and text-to-web; English and Spanish","results":[{"name":"Greg Abbott","party":"REP","percentage":48},{"name":"Gina Hinojosa","party":"DEM","percentage":47},{"name":"Someone else / Would not vote","percentage":2},{"name":"Do not know / Refused","percentage":3}],"published_on":"2026-10-13","review_status":"verified","evidence":{"release_pages":[2,3],"crosstabs_url":"https://sri.siena.edu/wp-content/uploads/2026/10/TXP004-Crosstabs.pdf","crosstabs_page":1,"margin_of_error_percentage_points":4.4},"review_notes":"Same underlying TXP004 survey as Senate result. Do not count as an independent survey when estimating shared national error. Verification covers source transcription only."}]'::jsonb) as p(source_id text,original_release_url text,external_poll_id text,race_id text,pollster text,sponsor text,field_start date,field_end date,sample_size integer,population text,method text,results jsonb,published_on date,review_status text,evidence jsonb,review_notes text)
on conflict(content_hash) do nothing;
select count(*) as verified_poll_observations from public.polls where review_status='verified';